def reverse_words(s):
    words = []
    current = []
    for ch in s:
        if ch == " ":
            if current:
                words.append("".join(current))
                current = []
        else:
            current.append(ch)
    if current:
        words.append("".join(current))
    left, right = 0, len(words) - 1
    while left < right:
        words[left], words[right] = words[right], words[left]
        left += 1
        right -= 1
    result = ""
    for i, word in enumerate(words):
        if i:
            result += " "
        result += word
    return result
